mapper.insert:
INSERT INTO tb_main /*MainDAO.insertMain*/
       (
             MAIN_ID
           , MAIN_NM
           , CONN_URL
           , MAIN_DSC
           , DEL_YN

               , MAIN_IMG_ID

           , CREAT_DTTM
           , CRTR_ID
           , UPDT_DTTM
           , UPDUSR_ID
       )
VALUES
       (
             (SELECT IFNULL(MAX(MAIN_ID) + 1, 1) FROM tb_main A)
           , #{mainNm}
           , #{connUrl}
           , #{mainDsc}
           , 'N'

               , #{mainImgId}

           , now()
           , #{crtrId}
           , now()
           , #{crtrId}
        )

mapper.update:
UPDATE tb_main /*MainDAO.updateMain*/
   SET MAIN_NM     = #{mainNm}
     , CONN_URL    = #{connUrl}
     , MAIN_DSC    = #{mainDsc}
     , DEL_YN      = 'N'

         , MAIN_IMG_ID = #{mainImgId}

     , UPDT_DTTM   = now()
     , UPDUSR_ID   = #{crtrId}
 WHERE MAIN_ID     = #{mainId}

UPDATE tb_main /*MainDAO.updateVideo*/
   SET VIDEO_SRC   = #{videoSrc}
     , DEL_YN      = 'N'
     , UPDT_DTTM   = now()
     , UPDUSR_ID   = #{crtrId}
 WHERE MAIN_ID     = #{mainId}

UPDATE tb_main /*MainDAO.updateMainDel*/
   SET DEL_YN      = 'Y'
     , UPDT_DTTM   = now()
     , UPDUSR_ID   = #{crtrId}
 WHERE MAIN_ID     = #{mainId}
